import RNA
import random, sys, math

target = '((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..)).'
n = len(target)

stack=[]; tpairs=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')': tpairs.append((stack.pop(), i))
pset = set(tpairs)
pmap = {i:j for i,j in tpairs}

def fold(seq):
    fc = RNA.fold_compound(''.join(seq))
    ss, mfe = fc.mfe()
    return ss, mfe

def bp_distance(ss):
    st=[]; sps=[]
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')': sps.append((st.pop(), i))
    spset=set(sps)
    return len(pset ^ spset)

def score(seq):
    ss,_ = fold(seq)
    return bp_distance(ss)

start = ""
seq = list(start)
cur = score(seq)
best = cur
bestseq = seq[:]
r = random.Random(7)

import time
deadline = time.time() + 280
T = 2.0
it = 0
while time.time() < deadline and best > 0:
    it += 1
    ss,_ = fold(seq)
    mism = [i for i in range(n) if ss[i]!=target[i]]
    if not mism:
        best = 0; bestseq = seq[:]; break
    i = r.choice(mism)
    orig = seq[i]
    # candidate: complementary base to target partner if paired; else random
    if i in pmap:
        j = pmap[i]
        comp = {'A':'U','U':'A','G':'C','C':'G'}
        b = comp[seq[j]]
    elif target[i]=='.':
        b = r.choice(['A','U'])
    else:
        b = r.choice(['A','C','G','U'])
    seq[i]=b
    s = score(seq)
    delta = s - cur
    if delta <= 0 or r.random() < math.exp(-delta/T):
        cur = s
        if s < best:
            best = s; bestseq = seq[:]
    else:
        seq[i]=orig
    T *= 0.9995
    if it % 500 == 0:
        print("it", it, "cur", cur, "best", best, "T", round(T,3), file=sys.stderr)

print("FINAL best", best, file=sys.stderr)
print(''.join(bestseq))
